@Entity(tableName = "outbox")
data class PendingOp(
  @PrimaryKey val opId: String,      // idempotency key: minted here, never regenerated
  val groupKey: String,              // aggregate root — the ordering scope
  val seq: Long,                     // monotonic within the group
  val entityType: String,
  val entityId: String,              // client-generated id of the target row
  val kind: String,                  // CREATE / UPDATE / DELETE
  val payloadJson: String,           // data, not a request
  val payloadVersion: Int,           // the shape the writing build used
  val baseVersion: Long? = null,     // optimistic concurrency
  val createdAt: Long,
  val status: String = "READY",
  val attempts: Int = 0,
  val nextAttemptAt: Long = 0,
  val lastError: String? = null
)

// Wrong: the call is built at enqueue time and frozen
class BadOp(val call: Call<Unit>)    // stale token, stale base URL, and gone after a restart

// Right: rebuilt from the row on every attempt, on whatever build is running now
suspend fun send(op: PendingOp): SendResult {
  val body = json.decodeFromString<NoteDto>(migrate(op.payloadJson, op.payloadVersion))
  return api.push(idempotencyKey = op.opId, ifMatch = op.baseVersion, body = body)
}

// The local row and its queued op are written together or not at all
suspend fun editNote(note: NoteEntity, body: String) = db.withTransaction {
  notes.upsert(note.copy(body = body, syncState = SyncState.PENDING))
  outbox.insert(
    PendingOp(
      opId = ulid(),
      groupKey = note.localId,
      seq = outbox.nextSeq(note.localId),
      entityType = "note",
      entityId = note.localId,
      kind = "UPDATE",
      payloadJson = json.encodeToString(note.toDto(body)),
      payloadVersion = PAYLOAD_V3,
      baseVersion = note.serverVersion,
      createdAt = clock.now()
    )
  )
}

enum class SyncState { SYNCED, PENDING, SENDING, FAILED }

@Entity(tableName = "notes")
data class NoteEntity(
  @PrimaryKey val localId: String,      // stable for the row's whole life
  val remoteId: String? = null,         // arrives later, never becomes the key
  val body: String,
  val createdAt: Long,                  // stable sort key, set once
  val syncState: SyncState = SyncState.PENDING,
  val deletedLocally: Boolean = false,
  val lastErrorCode: Int? = null
)

@Dao
interface NoteDao {
  @Query("SELECT * FROM notes WHERE deletedLocally = 0 ORDER BY createdAt DESC")
  fun observe(): Flow<List<NoteEntity>>  // the screen's only source of truth

  @Query("UPDATE notes SET remoteId = :remote, syncState = 'SYNCED' WHERE localId = :local")
  suspend fun markSynced(local: String, remote: String)
}

@Composable
fun NoteList(notes: List<NoteEntity>, onRetry: (String) -> Unit) {
  LazyColumn {
    // key on localId: an index key remounts on reorder, remoteId does not exist yet
    items(notes, key = { it.localId }) { note ->
      Row {
        Text(note.body)
        when (note.syncState) {
          SyncState.PENDING, SyncState.SENDING -> PendingBadge()
          SyncState.FAILED -> RetryButton(note.lastErrorCode) { onRetry(note.localId) }
          SyncState.SYNCED -> Unit
        }
      }
    }
  }
}

// Confirming updates in place. delete + insert remounts the item and it flashes.
suspend fun onAck(localId: String, remoteId: String) = dao.markSynced(localId, remoteId)

interface OrdersApi {
  @POST("orders")
  suspend fun create(
    @Header("Idempotency-Key") key: String,
    @Body body: CreateOrder
  ): Response<Order>
}

// Wrong: a fresh key per attempt turns every timeout into a second order
suspend fun createBad(body: CreateOrder): Order = retry(times = 3) {
  api.create(UUID.randomUUID().toString(), body).body()!!
}

// Right: the key is minted once and lives in the durable row
suspend fun enqueueOrder(body: CreateOrder) = db.withTransaction {
  outbox.insert(
    PendingOp(
      opId = UUID.randomUUID().toString(),   // minted here, exactly once
      kind = "CREATE_ORDER",
      payloadJson = json.encodeToString(body),
      createdAt = clock.now()
    )
  )
}

suspend fun drain(op: PendingOp) {
  val res = api.create(op.opId, json.decodeFromString(op.payloadJson))
  when {
    // 200 or the replayed 201 both mean "applied exactly once"
    res.isSuccessful -> db.withTransaction {
      orders.upsert(res.body()!!.toEntity())
      outbox.delete(op.opId)
    }
    res.code() == 409 -> outbox.backoff(op)              // same key still in flight server-side
    res.code() == 422 -> outbox.markPermanent(op)        // same key, different payload: a client bug
    res.code() in 500..599 -> outbox.backoff(op)
    else -> outbox.markPermanent(op)
  }
}

