  @PrimaryKey val localId: String,
  val postLocalId: String,           // references the LOCAL id: always resolvable offline
  val body: String
)

// Translation happens only at the API boundary
suspend fun CommentEntity.toDto(posts: PostDao) = CommentDto(
  id = localId,
  postId = posts.remoteIdOf(postLocalId) ?: postLocalId,
  body = body
)

// Wrong: adopting the server id as the primary key orphans children and queued ops
suspend fun onAckBad(local: String, remote: String) = db.withTransaction {
  val row = posts.get(local)
  posts.delete(local)
  posts.insert(row.copy(localId = remote))   // comments, outbox rows and list keys now dangle
}

// Right: the server id is a column, not an identity change
suspend fun onAck(local: String, remote: String) = posts.setRemoteId(local, remote)

@Dao
interface OutboxDao {
  @Query("SELECT DISTINCT groupKey FROM outbox WHERE status = 'READY' AND nextAttemptAt <= :now")
  suspend fun readyGroups(now: Long): List<String>

  // Strictly one op per group in flight, in seq order
  @Query("SELECT * FROM outbox WHERE groupKey = :g AND status = 'READY' ORDER BY seq LIMIT 1")
  suspend fun head(g: String): PendingOp?
}

suspend fun drain(dao: OutboxDao) = coroutineScope {
  dao.readyGroups(clock.now()).map { group ->
    launch {                                   // groups are independent: a stall stays local
      while (true) {
        val op = dao.head(group) ?: break
        when (send(op)) {
          SendResult.Sent -> dao.delete(op.opId)
          SendResult.Retryable -> { dao.backoff(op); break }   // blocks this group only
          SendResult.Permanent -> { dao.dropWithDependents(op); break }
        }
      }
    }
  }.joinAll()
}

// The parent reference is resolved at send time, not frozen at enqueue time
private suspend fun send(op: PendingOp): SendResult {
  val body = json.decodeFromString<CommentDto>(op.payloadJson)
  val parent = posts.remoteIdOf(body.postId) ?: body.postId  // still the client id if unsynced
  return api.push(op.opId, body.copy(postId = parent)).toSendResult()
}

@Serializable
data class Cursor(val updatedAt: Long, val id: String)   // composite: value + tie-break

@Serializable
data class DeltaPage(val rows: List<NoteDto>, val next: Cursor?, val hasMore: Boolean)

suspend fun pull() {
  var cursor = cursors.get("notes")
  while (true) {
    // The server does: WHERE (updated_at, id) > (:ts, :id) ORDER BY updated_at, id LIMIT 500
    val page = api.notesSince(cursor?.updatedAt, cursor?.id, limit = 500)
    db.withTransaction {
      notes.upsertAll(page.rows.map { it.toEntity() })   // upsert: a resent row is a no-op
      cursors.put("notes", page.next)                     // page and cursor commit together
    }
    cursor = page.next
    if (!page.hasMore) break
  }
}

// Wrong: a scalar cursor, a strict boundary, and a device clock
suspend fun pullBad() {
  val since = cursors.timestamp("notes")
  val rows = api.notesSince(since)                        // ... updated_at > since ORDER BY id
  cursors.putTimestamp("notes", System.currentTimeMillis())
  notes.upsertAll(rows.map { it.toEntity() })             // rows sharing `since` are gone for good,
}                                                         // and the cursor moved before the write

@Serializable
data class NoteDto(
  val id: String,
  val updatedAt: Long,
  val deleted: Boolean = false,      // the tombstone marker, carried in the delta
  val body: String? = null           // absent for a tombstone: deleted content is not shipped
)

@Serializable
data class DeltaPage(
  val rows: List<NoteDto>,
  val next: Cursor?,
  val tombstoneRetentionDays: Int    // the server advertises its promise, the client checks it
)

suspend fun sync() {
  val lastSynced = prefs.lastSyncedAt()
  val windowMillis = prefs.retentionDays() * 24L * 60 * 60 * 1000
  // Older than the window: deletes we never saw have already been purged
  if (lastSynced == null || clock.now() - lastSynced > windowMillis) {
    db.withTransaction { notes.clear(); cursors.clear() }
    fullResync()
    return
  }
  deltaPull()
}

private suspend fun apply(page: DeltaPage) = db.withTransaction {
  for (row in page.rows) {
    when {
      row.deleted && notes.isDirty(row.id) -> conflicts.record(row.id)  // our edit vs their delete
      row.deleted -> notes.delete(row.id)
      else -> notes.upsert(row.toEntity())
    }
  }
  cursors.put("notes", page.next)
  prefs.setLastSyncedAt(clock.now())
  prefs.setRetentionDays(page.tombstoneRetentionDays)
}

// LWW: one version for the whole record, compared on a server-assigned value
fun mergeLww(local: Note, remote: Note): Note =
  if (remote.serverVersion >= local.serverVersion) remote else local  // the loser's edits are gone

// Field level: a version per field, merged column by column
data class Versioned<T>(val value: T, val version: Long)

private fun <T> latest(a: Versioned<T>, b: Versioned<T>) = if (b.version >= a.version) b else a

fun mergeFields(local: Profile, remote: Profile) = Profile(
  name = latest(local.name, remote.name),
  bio = latest(local.bio, remote.bio)        // independent fields now survive each other
)

// OR-Set: adds carry unique tags, so a concurrent add beats a remove that never saw it
data class OrSet(
  val adds: Map<String, String> = emptyMap(),   // addId -> value
  val removes: Set<String> = emptySet()         // addIds this replica has removed
) {
  val value: Set<String> get() = adds.filterKeys { it !in removes }.values.toSet()

  fun add(tag: String) = copy(adds = adds + (ulid() to tag))
  fun remove(tag: String) = copy(removes = removes + adds.filterValues { it == tag }.keys)

  // Commutative, associative, idempotent: replay order and duplicates do not matter
  fun merge(other: OrSet) = OrSet(adds + other.adds, removes + other.removes)
}

// The counter needs none of this: ship the intent and let the server add it up
suspend fun like(postId: String) = outbox.enqueue(Mutation.Like(postId, delta = 1))

// Hybrid logical clock: sorts like a timestamp, ordered like a Lamport clock
data class Hlc(val millis: Long, val counter: Int, val nodeId: String) : Comparable<Hlc> {
  override fun compareTo(other: Hlc) =
    compareValuesBy(this, other, Hlc::millis, Hlc::counter, Hlc::nodeId)
  fun encode() = "%013d:%05d:%s".format(millis, counter, nodeId)
}

class HlcClock(private val nodeId: String, private val wall: () -> Long) {
  private var last = Hlc(0, 0, nodeId)

  @Synchronized fun now(): Hlc {
    val phys = wall()
    last = if (phys > last.millis) Hlc(phys, 0, nodeId) else last.copy(counter = last.counter + 1)
    return last
  }

  // Receiving a remote stamp drags us forward — this is what survives a slow phone
  @Synchronized fun observe(remote: Hlc): Hlc {
    val phys = maxOf(wall(), last.millis, remote.millis)
    val counter = when (phys) {
      last.millis, remote.millis -> maxOf(
        if (phys == last.millis) last.counter else -1,
        if (phys == remote.millis) remote.counter else -1,
      ) + 1
      else -> 0
    }
    last = Hlc(phys, counter, nodeId)
    return last
  }
}

// A version vector answers the other question: was this a real conflict?
enum class Rel { A_NEWER, B_NEWER, CONCURRENT, EQUAL }

fun relation(a: Map<String, Long>, b: Map<String, Long>): Rel {
  val keys = a.keys + b.keys
  val aAhead = keys.any { (a[it] ?: 0L) > (b[it] ?: 0L) }
  val bAhead = keys.any { (b[it] ?: 0L) > (a[it] ?: 0L) }
  return when {
    aAhead && bAhead -> Rel.CONCURRENT   // genuine conflict: merge or ask, never overwrite
    aAhead -> Rel.A_NEWER
    bAhead -> Rel.B_NEWER
    else -> Rel.EQUAL
  }
}

@Entity(tableName = "outbox")
data class Op(
  @PrimaryKey val id: String,        // also the idempotency key
  val chainKey: String,              // entity id: order is promised only inside a chain
  val seq: Long,
  val type: String,
  val payload: String,
  val attempts: Int = 0,
  val nextAttemptAt: Long = 0,
  val blockedBy: String? = null,
  val lastError: String? = null,
)

suspend fun drain(now: Long) = coroutineScope {
  // One worker per chain: different entities in parallel, the same entity never
  dao.readyChains(now).map { key -> async { drainChain(key) } }.awaitAll()
}

private suspend fun drainChain(chainKey: String) {
  while (true) {
    val op = dao.head(chainKey) ?: return
    when (val r = push(op)) {
      is Push.Ok -> db.withTransaction {          // apply and delete atomically
        applyServerState(r.entity)
        dao.delete(op.id)
      }
      is Push.Retryable -> {                      // 87 keeps the head; 88.. wait behind it
        dao.reschedule(op.id, op.attempts + 1, backoffDelay(op.attempts), r.message)
        return                                    // other chains keep draining
      }
      is Push.Permanent -> {
        db.withTransaction {
          failures.insert(op, r.code)
          dao.delete(op.id)
          dao.blockAfter(chainKey, op.seq, blockedBy = op.id)   // cascade, do not skip
          revertLocal(op)
        }
        return
      }
    }
  }
}

sealed interface Outcome {
  data class Done(val entity: EntityDto) : Outcome
  data object Retry : Outcome                          // I/O, 408, 425, 429, 5xx
  data object Reauth : Outcome                         // 401 — pause, do not drop
  data class Rebase(val server: EntityDto) : Outcome   // 409
  data class Permanent(val code: Int, val message: String?) : Outcome
}

fun classify(e: Throwable): Outcome = when (e) {
  is IOException -> Outcome.Retry
  is HttpException -> when (val code = e.code()) {
    401 -> Outcome.Reauth
    409 -> Outcome.Rebase(e.parseServerEntity())
    408, 425, 429 -> Outcome.Retry
    in 500..599 -> Outcome.Retry
    else -> Outcome.Permanent(code, e.message())        // 400/403/404/410/422
  }
  else -> Outcome.Permanent(-1, e.message)
}

// Dropping it is one transaction, and it must leave something the user can act on
suspend fun dropPermanently(op: Op, code: Int, message: String?) = db.withTransaction {
  outbox.delete(op.id)
  outbox.blockAfter(op.chainKey, op.seq, blockedBy = op.id)   // dependents are undeliverable too
  notes.markNotUploaded(op.entityId)                          // state on the row, not a toast
  failures.insert(
    SyncFailure(
      opId = op.id,
      entityId = op.entityId,
      code = code,
      message = message,
      payload = op.payload,        // keep it: this is the user's text, not debug data
      at = clock.now(),
    )
  )
}

