// eats the edit, and a 403 and a timeout become indistinguishable.

private const val CURRENT_NOTE_UPDATE = 3

// Self-describing row: stable type name, payload version, opaque body
@Entity(tableName = "outbox")
data class OpRow(
  @PrimaryKey val id: String,
  val type: String,            // "note.update" — a constant, never Class::getName
  val payloadVersion: Int,
  val payload: String,         // JSON text, not a serialized object graph
)

@Serializable
data class NoteUpdateV3(val noteId: String, val body: String, val tags: List<String>)

private val json = Json { ignoreUnknownKeys = true }   // tomorrow's extra keys must not throw

// One upgrade chain per type, applied on read
fun upgradeNoteUpdate(version: Int, raw: String): NoteUpdateV3 {
  var v = version
  var node = json.parseToJsonElement(raw).jsonObject

  if (v == 1) {                                        // v1 called the field "text"
    val body = node["text"] ?: JsonPrimitive("")
    node = JsonObject(node - "text" + ("body" to body))
    v = 2
  }
  if (v == 2) {                                        // v2 had no tags at all
    node = JsonObject(node + ("tags" to JsonArray(emptyList())))
    v = 3
  }
  check(v == CURRENT_NOTE_UPDATE) { "no upgrade path from v$version" }
  return json.decodeFromJsonElement(node)
}

suspend fun decode(row: OpRow): NoteUpdateV3? =
  runCatching { upgradeNoteUpdate(row.payloadVersion, row.payload) }
    .getOrElse { e ->
      // Never crash the drain, never silently delete: park it and count it
      deadLetter.insert(row, reason = e.message)
      outbox.delete(row.id)
      null
    }

@Entity(tableName = "attachments")
data class Attachment(
  @PrimaryKey val localId: String,
  val path: String,              // OUR copy — the picker's content URI is revoked, the file is not
  val bytes: Long,
  val sessionUrl: String? = null,
  val confirmedOffset: Long = 0,
  val blobId: String? = null,
)

private const val CHUNK = 4L * 1024 * 1024

suspend fun upload(a: Attachment): String {
  val session = a.sessionUrl
    ?: api.createSession(a.bytes).also { dao.setSession(a.localId, it) }

  // Trust the server's offset, not our last local write: a crash eats exactly that write
  var offset = api.probeOffset(session)
  val file = File(a.path)

  while (offset < a.bytes) {
    val end = minOf(offset + CHUNK, a.bytes) - 1
    api.putChunk(
      session,
      body = file.rangeBody(offset, end),              // streams one range, never file.readBytes()
      contentRange = "bytes $offset-$end/${a.bytes}",
    )
    offset = end + 1
    dao.setConfirmedOffset(a.localId, offset)          // resume point after process death
  }

  val blobId = api.finish(session)
  db.withTransaction {
    dao.setBlobId(a.localId, blobId)
    outbox.unblock(chainKey = a.localId)               // post.create was waiting on this
  }
  file.delete()                                        // give the disk back, only once confirmed
  return blobId
}

// Wrong: api.createPost(text, photoBytes = uri.readBytes())
// — 12 MB in RAM, no resume, and a revoked URI on the next process start.

private val BASE = 30.seconds
private val CAP = 6.hours

// Full jitter: two devices that failed together must not retry together
fun backoffDelay(attempt: Int, retryAfter: Duration? = null): Duration {
  retryAfter?.let { return it }                              // the server's number wins
  val exp = BASE * (1 shl attempt.coerceAtMost(10))
  val capped = minOf(exp, CAP)
  return Random.nextLong(0, capped.inWholeMilliseconds + 1).milliseconds
}

// A periodic job installed by everyone still fires in lockstep unless its phase is per-install
fun schedulePeriodic(ctx: Context, installId: String) {
  val phaseMinutes = (installId.hashCode().toLong() and 0x7fffffffL) % 360  // stable, not Random()
  val work = PeriodicWorkRequestBuilder<SyncWorker>(6, TimeUnit.HOURS)
    .setInitialDelay(phaseMinutes, TimeUnit.MINUTES)
    .setConstraints(
      Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build()
    )
    .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
    .build()
  WorkManager.getInstance(ctx)
    .enqueueUniquePeriodicWork("sync", ExistingPeriodicWorkPolicy.KEEP, work)
}

// Every trigger coalesces into one unique job instead of starting its own drain
fun kick(ctx: Context, reason: String) {
  val req = OneTimeWorkRequestBuilder<SyncWorker>()
    .setInputData(workDataOf("reason" to reason))
    .setConstraints(
      Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build()
    )
    .build()
  WorkManager.getInstance(ctx)
    .enqueueUniqueWork("sync-now", ExistingWorkPolicy.KEEP, req)
}

// Wrong: connectivity.onAvailable { drainNow() } — one tower recovering is
// a synchronized starting gun for every device attached to it.

class FakeServer(private val rnd: Random) {
  val state = mutableMapOf<String, Note>()
  val applyCount = mutableMapOf<String, Int>()      // op id -> times it really mutated state
  private val seen = mutableMapOf<String, Note>()   // idempotency key -> original result
  var faults: FaultPlan = FaultPlan.none

  fun push(op: Op): Note {
    if (faults.dropRequest(rnd)) throw IOException("partition")
    seen[op.id]?.let { return it }                  // duplicate delivery must be a no-op
    val applied = apply(op)
    applyCount[op.id] = (applyCount[op.id] ?: 0) + 1
    state[op.entityId] = applied
    seen[op.id] = applied
    if (faults.dropResponse(rnd)) throw IOException("lost ack")   // applied, client never learns
    return applied
  }
}

@Test
fun convergesUnderPartitionDuplicatesAndReordering() = runTest {
  repeat(2_000) { seed ->
    val rnd = Random(seed)
    val server = FakeServer(rnd)
    val a = Device("a", server, TestClock(), rnd)
    val b = Device("b", server, TestClock(), rnd)

    server.faults = FaultPlan.chaotic(rnd)
    randomOps(rnd).forEach { it.applyTo(if (rnd.nextBoolean()) a else b) }
    repeat(20) { a.drain(); b.drain(); advanceUntilIdle() }   // backoff collapses to nothing

    server.faults = FaultPlan.none                            // heal, then let it settle
    repeat(5) { a.drain(); b.drain(); a.pull(); b.pull(); advanceUntilIdle() }

    assertEquals(server.state, a.state, "seed=$seed")         // convergence
    assertEquals(server.state, b.state, "seed=$seed")
    // No silent loss: every mutation the UI accepted is applied or explicitly failed
    assertEquals(a.acceptedOpIds, server.applyCount.keys + a.failedOpIds, "seed=$seed")
    assertTrue(server.applyCount.values.all { it == 1 }, "seed=$seed")   // idempotency held
  }
}
